template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 58mm;
  height: 40mm;
  padding: 2.4mm 2.6mm 2mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.name {
  font-size: 12px;
  font-weight: 700;
  line-height: 1.2;
  max-height: 2.4em;
  overflow: hidden;
}
.price {
  font-size: 20px;
  font-weight: 800;
  margin-top: 1.2mm;
  line-height: 1;
  letter-spacing: -0.02em;
}
.currency {
  font-size: 11px;
  font-weight: 700;
  margin-left: 1mm;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5mm;
  margin-top: auto;
  width: 100%;
}
.code {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-align: center;
  white-space: nowrap;
}
img.barcode {
  height: 15mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
